 assert.deepEqual(reference.manifest,prefix,'RESET_HISTORICAL_REFERENCE_MANIFEST_CHANGED');assert.equal(reference.manifestDigest,manifestDigest(prefix),'RESET_HISTORICAL_REFERENCE_MANIFEST_CHANGED');
