 const guard="DO $reset225_existing_cron$ BEGIN IF (SELECT count(*) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='pg_cron' AND e.extversion="+literal(identity.version)+" AND n.nspname="+literal(identity.schema)+" AND pg_get_userbyid(e.extowner)="+literal(identity.owner)+")<>1 THEN RAISE EXCEPTION 'RESET225_PG_CRON_IDENTITY_MISMATCH'; END IF; END $reset225_existing_cron$;";
